import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)

    def _expiry(self):
        if self.ttl is None:
            return None
        return self.clock() + self.ttl

    def _expired(self, expires_at):
        return expires_at is not None and self.clock() >= expires_at

    def _purge_expired(self):
        for key, (_, expires_at) in list(self._data.items()):
            if self._expired(expires_at):
                del self._data[key]

    def get(self, key, default=None):
        try:
            value, expires_at = self._data[key]
        except KeyError:
            return default
        if self._expired(expires_at):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def put(self, key, value):
        self._purge_expired()
        self._data[key] = (value, self._expiry())
        self._data.move_to_end(key)
        while len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __len__(self):
        self._purge_expired()
        return len(self._data)

    def __contains__(self, key):
        entry = self._data.get(key)
        return entry is not None and not self._expired(entry[1])
```

